// Generated by official Feel.words('snappy, precise').params at the commit above.
// Mass 1 is the vocabulary's normal UI body; geometric-mean frequency 3.9115 Hz
// combines quick response with precision; mean damping ratio 0.91 suppresses
// visible ringing. These imply k = 604.019789 and c = 44.729802, not a duration.
const PARAMS = { mass: 1, stiffness: 604.0197893466687, damping: 44.729801589453814 }
const TRAVEL = 16 // Track width 36 minus thumb width 16 minus two 2px insets.
const OMEGA = Math.sqrt(PARAMS.stiffness / PARAMS.mass)
const ZETA = PARAMS.damping / (2 * Math.sqrt(PARAMS.stiffness * PARAMS.mass))
const DAMPED_OMEGA = OMEGA * Math.sqrt(1 - ZETA * ZETA)

/** Exact underdamped solution from Feel.response; this fixed vocabulary blend has ζ < 1. */
function response(displacement: number, velocity: number, seconds: number): readonly [number, number] {
  const a = displacement
  const b = (velocity + ZETA * OMEGA * displacement) / DAMPED_OMEGA
  const decay = Math.exp(-ZETA * OMEGA * seconds)
  const cosine = Math.cos(DAMPED_OMEGA * seconds)
  const sine = Math.sin(DAMPED_OMEGA * seconds)
  return [
    decay * (a * cosine + b * sine),
    decay * ((b * DAMPED_OMEGA - ZETA * OMEGA * a) * cosine
      - (a * DAMPED_OMEGA + ZETA * OMEGA * b) * sine),
  ]
}

/**
 * Create an instance-owned target spring without shared bodies or React frame updates.
 * @param element - The switch button whose visual properties follow the body.
 * @param checked - Initial controlled state, painted at rest without an entrance motion.
 * @returns Target updates and a disposer for the frame and preference listener.
 */
export function createFeelSwitchMotion(
  element: HTMLButtonElement,
  checked: boolean,
): { to(next: boolean): void; dispose(): void } {
  let position = checked ? TRAVEL : 0
  let target = position
  let velocity = 0
  let last = performance.now()
  let frame: number | null = null
  let disposed = false
  const media = typeof matchMedia === 'function' ? matchMedia('(prefers-reduced-motion: reduce)') : undefined
  let reduced = media?.matches ?? false

  const paint = () => {
    element.style.setProperty('--dsh-switch-x', `${position}px`)
    element.style.setProperty('--dsh-switch-fill', `${position / TRAVEL * 100}%`)
  }
  const cancel = () => {
    if (frame !== null) cancelAnimationFrame(frame)
    frame = null
  }
  const jump = () => {
    cancel()
    position = target
    velocity = 0
    paint()
  }
  const advance = (time: number) => {
    const [displacement, nextVelocity] = response(position - target, velocity, Math.max(0, time - last) / 1000)
    position = target + displacement
    velocity = nextVelocity
    // Inelastic end walls keep the thumb inside its physical track. Unlike the
    // runtime's soft walls, contact absorbs outward velocity rather than stretching.
    if (position < 0) { position = 0; velocity = 0 }
    if (position > TRAVEL) { position = TRAVEL; velocity = 0 }
    last = time
  }
  const tick = (time: number) => {
    frame = null
    if (disposed) return
    advance(time)
    // Subpixel rest tolerance: stop only below 0.01px displacement and 0.01px/s.
    if (Math.abs(position - target) < 0.01 && Math.abs(velocity) < 0.01) {
      position = target
      velocity = 0
    } else {
      frame = requestAnimationFrame(tick)
    }
    paint()
  }
  const onMotionPreference = (event: MediaQueryListEvent) => {
    reduced = event.matches
    if (reduced) jump()
  }
  media?.addEventListener('change', onMotionPreference)
  paint()

  return {
    to(next: boolean) {
      if (disposed) return
      const nextTarget = next ? TRAVEL : 0
      if (nextTarget === target) return
      advance(performance.now())
      target = nextTarget
      // Retargeting preserves the current position and velocity; it never queues
      // an animation or restarts a step from either endpoint.
      if (reduced || typeof requestAnimationFrame !== 'function') jump()
      else {
        paint()
        if (frame === null) frame = requestAnimationFrame(tick)
      }
    },
    dispose() {
      disposed = true
      cancel()
      media?.removeEventListener('change', onMotionPreference)
    },
  }
}
